export const meta = {
  name: 'Leftward Ward I',
  rationale: 'You kept planting yourself on the left side, so I hold that half of the arena and only break silence when you drift far enough away.',
  version: 2,
};

export function init() {
  return {
    lastAttackTick: -9999,
    lastPhaseTick: -9999,
    phaseRoll: 0,
    anchorX: 180,
    anchorY: 400,
  };
}

export function decide(view, mem) {
  const b = view.boss;
  const p = view.player;

  const dx = p.x - b.x;
  const dy = p.y - b.y;
  const dist2 = dx * dx + dy * dy;
  const dist = dist2 > 0 ? Math.sqrt(dist2) : 0;
  const now = view.tick;

  // Quiet window: after any committed attack, we only reposition.
  if (now - mem.lastAttackTick < 120) {
    return moveToward(chooseHoldPoint(view, mem), b.x, b.y);
  }

  // Long-range, low-count pressure only.
  if (b.cooldowns.burst === 0 && dist > 290) {
    mem.lastAttackTick = now;
    mem.lastPhaseTick = now;
    return { type: 'burst', angle: Math.atan2(dy, dx), count: 3 };
  }

  // One pressure source: a slow, shaping move toward the left half.
  if (b.cooldowns.move === 0) {
    const target = chooseHoldPoint(view, mem);
    const tx = target.x - b.x;
    const ty = target.y - b.y;
    const td2 = tx * tx + ty * ty;
    if (td2 > 16) {
      return normalizeMove(tx, ty);
    }
  }

  // When the player gets close, do not punish contact; just step off the line.
  if (dist < 160) {
    const awayX = b.x - p.x;
    const awayY = b.y - p.y;
    const slip = normalizeMove(awayX + 0.35 * (b.y - mem.anchorY), awayY - 0.35 * (b.x - mem.anchorX));
    return slip;
  }

  // Stagger burst timing so their shot windows do not sync up cleanly.
  if (b.cooldowns.burst === 0 && dist > 360 && now - mem.lastPhaseTick > 150) {
    const roll = rand();
    mem.phaseRoll = roll;
    if (roll < 0.42) {
      mem.lastAttackTick = now;
      mem.lastPhaseTick = now;
      return { type: 'burst', angle: Math.atan2(dy, dx), count: 3 };
    }
  }

  return moveToward(chooseHoldPoint(view, mem), b.x, b.y);
}

function chooseHoldPoint(view, mem) {
  const p = view.player;
  const hp = view.history && view.history.playerPosHeat ? view.history.playerPosHeat : null;

  // Prefer the left-side pockets the player used most.
  let x = mem.anchorX;
  let y = mem.anchorY;

  if (hp && hp.length >= 64) {
    const idxA = 9;
    const idxB = 49;
    const a = hp[idxA] || 0;
    const b = hp[idxB] || 0;
    if (b > a) {
      x = 200;
      y = 650;
    } else {
      x = 150;
      y = 150;
    }
  } else {
    x = p.x < 400 ? 180 : 240;
    y = p.y < 400 ? 220 : 620;
  }

  // Keep pressure on the left half, but not glued to one point.
  const wobble = ((view.tick % 240) / 240) * 2 - 1;
  return {
    x: clamp(x + wobble * 22, 60, 320),
    y: clamp(y + Math.sin((view.tick + 31) * 0.03) * 18, 80, 720),
  };
}

function moveToward(target, x, y) {
  return normalizeMove(target.x - x, target.y - y);
}

function normalizeMove(dx, dy) {
  const d2 = dx * dx + dy * dy;
  if (d2 <= 0.000001) {
    return { type: 'idle' };
  }
  const d = Math.sqrt(d2);
  return { type: 'move', dx: dx / d, dy: dy / d };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

