export const meta = {
  name: 'Lantern II',
  rationale: 'You keep anchoring on the left, so I seed that side with minions, then I take a 50/50 swing when you try to break out.',
  version: 2,
};

export function init() {
  return {
    nextSpawnTick: 0,
    recoverUntil: 0,
    lastBurstTick: -9999,
    lastChargeTick: -9999,
  };
}

export function decide(view, mem) {
  const b = view.boss;
  const p = view.player;
  const tick = view.tick;

  const dx = p.x - b.x;
  const dy = p.y - b.y;
  const dist2 = dx * dx + dy * dy;
  const dist = dist2 > 0 ? Math.sqrt(dist2) : 0;
  const ang = dist > 0 ? Math.atan2(dy, dx) : 0;

  // Keep pressure biased to the left-side pockets the player liked.
  const pocketY = p.y < view.arena.h * 0.5 ? 160 : 650;
  const pressX = p.x < 300 ? 120 : 240;
  const pressY = p.y < 400 ? pocketY : 400;

  // Slow spawn cadence: one big setup every ~420 ticks, not a constant flood.
  if (b.cooldowns.spawn === 0 && tick >= mem.nextSpawnTick) {
    mem.nextSpawnTick = tick + 420;
    mem.recoverUntil = tick + 35;
    return {
      type: 'spawn',
      x: clamp(pressX + (p.y < 400 ? 20 : 40), 40, view.arena.w - 40),
      y: clamp(pressY, 40, view.arena.h - 40),
    };
  }

  // Signature punish: only half the time, so it is answerable and not oppressive.
  // Aim for the escape lanes they used, especially after short dashes.
  if (b.cooldowns.burst === 0 && tick >= mem.recoverUntil) {
    const close = dist < 310;
    const dashy = p.isDashing || tick - p.lastShotTick <= 12;
    if (close && (dashy || dist < 220) && rand() < 0.5) {
      mem.lastBurstTick = tick;
      mem.recoverUntil = tick + 24;
      return { type: 'burst', angle: ang, count: dist < 150 ? 8 : 5 };
    }
  }

  // Charge only as a punish window, not as endless chase.
  if (b.cooldowns.charge === 0 && tick >= mem.recoverUntil) {
    const leftHalf = p.x < 320;
    if ((p.isDashing && dist < 280) || (leftHalf && dist < 240 && rand() < 0.35)) {
      mem.lastChargeTick = tick;
      mem.recoverUntil = tick + 22;
      return { type: 'charge', angle: ang };
    }
  }

  // Light movement: stay measured, cut off the left-side anchors, and avoid
  // lining up too cleanly with the player's shot-farming windows.
  if (tick < mem.recoverUntil) {
    return { type: 'idle' };
  }

  let tx = pressX;
  let ty = pressY;

  // If they're far right, step inward; if they're left, mirror their pocket.
  if (p.x < 260) {
    tx = p.x < 180 ? 140 : 220;
    ty = p.y < 400 ? 180 : 640;
  } else {
    tx = 260;
    ty = 400;
  }

  const mdx = tx - b.x;
  const mdy = ty - b.y;
  const md2 = mdx * mdx + mdy * mdy;
  if (md2 < 9) return { type: 'idle' };
  const ml = Math.sqrt(md2);
  return { type: 'move', dx: mdx / ml, dy: mdy / ml };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

