export const meta = {
  name: 'Warden III',
  rationale: 'You keep camping the left pockets, so I seed them with minions, slam them with full rings at contact, and charge the little escapes that try to slip out.',
  version: 2,
};

export function init() {
  return { phase: 0, lastSpawnTick: -9999 };
}

export function decide(view, mem) {
  const b = view.boss;
  const p = view.player;
  const w = view.arena.w;
  const h = view.arena.h;

  const dx = p.x - b.x;
  const dy = p.y - b.y;
  const d2 = dx * dx + dy * dy;
  const dist = Math.sqrt(d2) || 1;
  const ang = Math.atan2(dy, dx);

  // Three pressure sources: spawn, burst, charge.
  // Full ring at contact; this is the punish for rushing or planting.
  if (b.cooldowns.burst === 0 && dist < 155) {
    mem.phase = (mem.phase + 1) | 0;
    return { type: 'burst', angle: ang, count: 8 };
  }

  // Use charge to cut off short dash escapes and keep the fight from resetting.
  if (b.cooldowns.charge === 0 && dist > 120) {
    mem.phase = (mem.phase + 1) | 0;
    return { type: 'charge', angle: ang };
  }

  // Spawn whenever it is available. Favor the player’s left-side living space.
  if (b.cooldowns.spawn === 0) {
    mem.lastSpawnTick = view.tick;
    mem.phase = (mem.phase + 1) | 0;

    const hx = avg(view.history.playerPosHeat, 0, 1, 2, 3, 4, 5) + avg(view.history.playerPosHeat, 48, 49, 50, 51, 52, 53);
    const hy1 = avg(view.history.playerPosHeat, 8, 9, 10, 11, 12, 13);
    const hy2 = avg(view.history.playerPosHeat, 49, 50, 57, 58, 59, 60);

    let sx;
    let sy;

    if (hx >= hy1 && hx >= hy2) {
      // Left-half pressure: their two anchor pockets were around y≈150 and y≈650.
      if ((mem.phase & 1) === 0) {
        sx = 120 + 40 * (rand() - 0.5);
        sy = 150 + 26 * (rand() - 0.5);
      } else {
        sx = 180 + 60 * (rand() - 0.5);
        sy = 650 + 30 * (rand() - 0.5);
      }
    } else {
      // Otherwise, pin the current side and deny clean re-entry.
      sx = clamp(p.x + 80 * signNonZero(dx || (rand() - 0.5)), 40, w - 40);
      sy = clamp(p.y + 80 * signNonZero(dy || (rand() - 0.5)), 40, h - 40);
    }

    return { type: 'spawn', x: sx, y: sy };
  }

  // Keep moving into the player’s space; do not give the camper a quiet window.
  // Slight bias toward the left-side pockets we saw in the replay.
  let tx = p.x;
  let ty = p.y;

  if (p.x < 320) {
    tx = p.x < 220 ? 140 : 240;
    ty = p.y < 400 ? 150 : 650;
  } else {
    tx = p.x;
    ty = p.y;
  }

  const mx = tx - b.x;
  const my = ty - b.y;
  const md = Math.sqrt(mx * mx + my * my) || 1;

  return { type: 'move', dx: mx / md, dy: my / md };
}

function avg(arr, a, b, c, d, e, f) {
  const x0 = arr[a] || 0;
  const x1 = arr[b] || 0;
  const x2 = arr[c] || 0;
  const x3 = arr[d] || 0;
  const x4 = arr[e] || 0;
  const x5 = arr[f] || 0;
  return (x0 + x1 + x2 + x3 + x4 + x5) / 6;
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function signNonZero(v) {
  return v < 0 ? -1 : 1;
}

