export const meta = {
  name: 'Leftward Ward III',
  rationale: 'You kept planting yourself on the left side, so I seed that half of the arena, but I leave you gaps to think you still have a way out.',
  version: 2,
};

export function init() {
  return {
    lastAttackTick: -9999,
    lastPhaseTick: -9999,
    phaseRoll: 0,
    anchorX: 180,
    anchorY: 400,
    nextSpawnTick: 0,
    recoverUntil: 0,
  };
}

export function decide(view, mem) {
  const b = view.boss;
  const p = view.player;
  const now = view.tick;

  const dx = p.x - b.x;
  const dy = p.y - b.y;
  const dist2 = dx * dx + dy * dy;
  const dist = dist2 > 0 ? Math.sqrt(dist2) : 0;

  // Seed the left half, but not every cycle.
  if (b.cooldowns.spawn === 0 && now >= mem.nextSpawnTick && rand() < 0.7) {
    mem.nextSpawnTick = now + 420;
    mem.recoverUntil = now + 28;
    return {
      type: 'spawn',
      x: clamp((p.x < 300 ? 130 : 240) + (p.y < 400 ? 18 : 36), 40, view.arena.w - 40),
      y: clamp(p.y < 400 ? 175 : 640, 40, view.arena.h - 40),
    };
  }

  // Quiet window: after a committed attack, we only reposition.
  if (now - mem.lastAttackTick < 110 || now < mem.recoverUntil) {
    return moveToward(chooseHoldPoint(view, mem), b.x, b.y);
  }

  // Long-range pressure only; no unconditional contact punish.
  if (b.cooldowns.burst === 0) {
    const close = dist < 320;
    const risky = dist < 200;
    if ((close || risky) && rand() < 0.7) {
      mem.lastAttackTick = now;
      mem.lastPhaseTick = now;
      mem.recoverUntil = now + 22;
      return {
        type: 'burst',
        angle: safeAngle(dy, dx),
        count: risky ? 5 : 3,
      };
    }
  }

  // Charge only as a limited punish window, mostly against short dash escapes.
  if (b.cooldowns.charge === 0) {
    const leftHalf = p.x < 320;
    if ((p.isDashing && dist < 260) || (leftHalf && dist < 220 && rand() < 0.35)) {
      mem.lastAttackTick = now;
      mem.lastPhaseTick = now;
      mem.recoverUntil = now + 20;
      return { type: 'charge', angle: safeAngle(dy, dx) };
    }
  }

  // Stagger burst timing so their shot windows do not sync up cleanly.
  if (b.cooldowns.burst === 0 && dist > 250 && now - mem.lastPhaseTick > 140) {
    const roll = rand();
    mem.phaseRoll = roll;
    if (roll < 0.42) {
      mem.lastAttackTick = now;
      mem.lastPhaseTick = now;
      mem.recoverUntil = now + 18;
      return {
        type: 'burst',
        angle: safeAngle(dy, dx),
        count: dist > 360 ? 3 : 5,
      };
    }
  }

  // One pressure source: shape toward the left-half pockets, but not glued to one point.
  const target = chooseHoldPoint(view, mem);
  const tx = target.x - b.x;
  const ty = target.y - b.y;
  const td2 = tx * tx + ty * ty;
  if (td2 > 16 && b.cooldowns.move === 0) {
    return normalizeMove(tx, ty);
  }

  // When the player gets close, step off the line instead of punishing contact directly.
  if (dist < 160) {
    const awayX = b.x - p.x;
    const awayY = b.y - p.y;
    return normalizeMove(awayX + 0.35 * (b.y - mem.anchorY), awayY - 0.35 * (b.x - mem.anchorX));
  }

  return moveToward(target, b.x, b.y);
}

function chooseHoldPoint(view, mem) {
  const p = view.player;
  const hp = view.history && view.history.playerPosHeat ? view.history.playerPosHeat : null;

  let x = mem.anchorX;
  let y = mem.anchorY;

  if (hp && hp.length >= 64) {
    const a = hp[9] || 0;
    const b = hp[49] || 0;
    if (b > a) {
      x = 200;
      y = 650;
    } else {
      x = 150;
      y = 150;
    }
  } else {
    x = p.x < 400 ? 180 : 240;
    y = p.y < 400 ? 220 : 620;
  }

  const wobble = ((view.tick % 240) / 240) * 2 - 1;
  return {
    x: clamp(x + wobble * 22, 60, 320),
    y: clamp(y + Math.sin((view.tick + 31) * 0.03) * 18, 80, 720),
  };
}

function moveToward(target, x, y) {
  return normalizeMove(target.x - x, target.y - y);
}

function normalizeMove(dx, dy) {
  const d2 = dx * dx + dy * dy;
  if (d2 <= 0.000001) return { type: 'idle' };
  const d = Math.sqrt(d2);
  return { type: 'move', dx: dx / d, dy: dy / d };
}

function safeAngle(dy, dx) {
  if (!isFinite(dy) || !isFinite(dx)) return 0;
  if (dx === 0 && dy === 0) return 0;
  return Math.atan2(dy, dx);
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

