  const ang = dist > 0 ? Math.atan2(dy, dx) : 0;

  // Bias pressure toward the left-side pockets, but do not glue to them.
  const pocketY = p.y < view.arena.h * 0.5 ? 160 : 650;
  const pressX = p.x < 300 ? 140 : 240;
  const pressY = p.y < 400 ? pocketY : 400;

  // Slower spawn cadence; only some setups trigger.
  if (b.cooldowns.spawn === 0 && tick >= mem.nextSpawnTick && rand() < 0.28) {
    mem.nextSpawnTick = tick + 620;
    mem.recoverUntil = tick + 36;
    return {
      type: 'spawn',
      x: clamp(pressX + (p.y < 400 ? 18 : 36), 40, view.arena.w - 40),
      y: clamp(pressY, 40, view.arena.h - 40),
    };
  }

  // Signature punish: gated behind the bisection ratio, and only when they are
  // actually trying to slip away or farm a stable pocket.
  if (b.cooldowns.burst === 0 && tick >= mem.recoverUntil) {
    const close = dist < 300;
    const dashy = p.isDashing || tick - p.lastShotTick <= 12;
    if (close && (dashy || dist < 210) && rand() < 0.31) {
      mem.lastBurstTick = tick;
      mem.recoverUntil = tick + 24;
      return { type: 'burst', angle: ang, count: dist < 160 ? 5 : 3 };
    }
  }

  // Charge is a narrow punish, not a chase tool.
  if (b.cooldowns.charge === 0 && tick >= mem.recoverUntil) {
    const leftHalf = p.x < 320;
    if ((p.isDashing && dist < 240) || (leftHalf && dist < 200 && rand() < 0.31)) {
      mem.lastChargeTick = tick;
      mem.recoverUntil = tick + 24;
