export const meta = {
  name: 'Lantern III',
  rationale: 'You keep anchoring on the left, so I seed that side with only some of my punishments and leave you room to think you have an exit.',
  version: 2,
};

export function init() {
  return {
    nextSpawnTick: 0,
    recoverUntil: 0,
    lastBurstTick: -9999,
    lastChargeTick: -9999,
  };
}

export function decide(view, mem) {
  const b = view.boss;
  const p = view.player;
  const tick = view.tick;

  const dx = p.x - b.x;
  const dy = p.y - b.y;
  const dist2 = dx * dx + dy * dy;
  const dist = dist2 > 0 ? Math.sqrt(dist2) : 0;
  const ang = dist > 0 ? Math.atan2(dy, dx) : 0;

  // Bias pressure toward the left-side pockets, but do not glue to them.
  const pocketY = p.y < view.arena.h * 0.5 ? 160 : 650;
  const pressX = p.x < 300 ? 140 : 240;
  const pressY = p.y < 400 ? pocketY : 400;

  // Slower spawn cadence than the harder file; only some setups trigger.
  if (b.cooldowns.spawn === 0 && tick >= mem.nextSpawnTick && rand() < 0.22) {
    mem.nextSpawnTick = tick + 720;
    mem.recoverUntil = tick + 32;
    return {
      type: 'spawn',
      x: clamp(pressX + (p.y < 400 ? 16 : 28), 40, view.arena.w - 40),
      y: clamp(pressY, 40, view.arena.h - 40),
    };
  }

  // Signature punish: gated behind a lower roll, and only when they are
  // actually trying to slip away or farm a stable pocket.
  if (b.cooldowns.burst === 0 && tick >= mem.recoverUntil) {
    const close = dist < 290;
    const dashy = p.isDashing || tick - p.lastShotTick <= 12;
    if (close && (dashy || dist < 190) && rand() < 0.22) {
      mem.lastBurstTick = tick;
      mem.recoverUntil = tick + 26;
      return { type: 'burst', angle: ang, count: dist < 140 ? 5 : 3 };
    }
  }

  // Charge is a narrow punish, not a chase tool.
  if (b.cooldowns.charge === 0 && tick >= mem.recoverUntil) {
    const leftHalf = p.x < 320;
    if ((p.isDashing && dist < 240) || (leftHalf && dist < 190 && rand() < 0.18)) {
      mem.lastChargeTick = tick;
      mem.recoverUntil = tick + 24;
      return { type: 'charge', angle: ang };
    }
  }

  // Quiet recovery after a committed attack.
  if (tick < mem.recoverUntil) {
    return { type: 'idle' };
  }

  // Low-pressure movement: cut off the left-side anchors, but keep a lane open.
  let tx = pressX;
  let ty = pressY;

  if (p.x < 260) {
    tx = p.x < 180 ? 150 : 220;
    ty = p.y < 400 ? 180 : 640;
  } else {
    tx = 260;
    ty = 400;
  }

  const mdx = tx - b.x;
  const mdy = ty - b.y;
  const md2 = mdx * mdx + mdy * mdy;
  if (md2 < 9) {
    return { type: 'idle' };
  }

  const ml = Math.sqrt(md2);
  return { type: 'move', dx: mdx / ml, dy: mdy / ml };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

